export const useGetUser = () => {
  const { user, updateUser } = useUserContext();
  const [loading, setLoading] = useState(!user);
  const [error, setError] = useState<Error | null>(null);

  const getUser = async () => {
    // 1️⃣ Return from global state if exists
    if (user) return user;

    let token = getAccessToken();
    
    // 2️⃣ Try to refresh access token if missing
    if (!token) {
      console.log('no token')
      try {
        const refreshRes = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/auth/refresh`, {
          method: "POST",
          credentials: "include", // send HttpOnly cookie
        });

        

        if (!refreshRes.ok) {
          clearAccessToken();
          return null;
        }

        const data = await refreshRes.json();
        token = data.accessToken;
        setAccessToken(token);
      } catch (err) {
        console.error("Refresh token failed", err);
        clearAccessToken();
        return null;
      }
    }

    // 3️⃣ Check localStorage cache
    try {
      const storedJSON = localStorage.getItem("user-data");
      if (storedJSON) {
        console.log('stored json')
        const storedUser = JSON.parse(storedJSON);
        updateUser(storedUser);
        return storedUser;
      }
    } catch (err) {
      console.error("Failed to read/parse user from localStorage", err);
      localStorage.removeItem("user-data"); // clear corrupted data
    }

    // 4️⃣ Fetch user from API
    try {
      console.log('fetching...')
      const res = await apiFetch(`${process.env.NEXT_PUBLIC_API_URL}/user/simple`);
      if (!res || !res.ok) {
        return null;
      }

      const userData = await res.json();
      localStorage.setItem("user-data", JSON.stringify(userData));
      updateUser(userData);

      return userData;
    } catch (err: any) {
      console.error("Failed to fetch user", err);
      return null;
    }
  };

  useEffect(() => {
    const fetchUser = async () => {
      if (!user) {
        setLoading(true);
        try {
          await getUser();
        } catch (err: any) {
          setError(err);
        } finally {
          setLoading(false);
        }
      }
    };
    fetchUser();
  }, [user]);

  return { user, loading, error, refetch: getUser, updateUser };
};